    from item i where i.world_id = p_world and i.holder = 'ground' and i.gx = p_x and i.gy = p_y;
  if v_ids is null then
    return jsonb_build_object('why', 'Nothing is lying on the ground at (' || p_x || ', ' || p_y || ').');
